package com.sharehope.event.service;
import com.sharehope.event.dto.*; import com.sharehope.event.model.Event; import com.sharehope.event.repository.EventRepository; import com.sharehope.exception.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.ZoneId; import java.util.*;
@Service @RequiredArgsConstructor
public class EventService {
 private final EventRepository repository;
 private final com.sharehope.event.repository.EventRegistrationRepository registrationRepository;
 @Transactional(readOnly=true) public List<EventResponse> adminList(){return repository.findAllByOrderByStartAtAscDisplayOrderAsc().stream().map(this::admin).toList();}
 @Transactional(readOnly=true) public List<PublicEventResponse> publicList(String locale){validLocale(locale);return repository.findByStatusOrderByStartAtAscDisplayOrderAsc("PUBLISHED").stream().map(e->localized(e,locale)).toList();}
 @Transactional(readOnly=true) public PublicEventResponse publicOne(String slug,String locale){validLocale(locale);Event event=repository.findBySlug(slug).filter(e->"PUBLISHED".equals(e.getStatus())).orElseThrow(()->new ResourceNotFoundException("Event not found."));return localized(event,locale);}
 @Transactional public EventResponse create(EventRequest r){if(repository.findBySlug(r.slug()).isPresent())throw new ResourceAlreadyExistsException("Event slug already exists.");Event e=new Event();e.setId(UUID.randomUUID());apply(e,r);return admin(repository.save(e));}
 @Transactional public EventResponse update(UUID id,EventRequest r){Event e=get(id);if(repository.existsBySlugAndIdNot(r.slug(),id))throw new ResourceAlreadyExistsException("Event slug already exists.");apply(e,r);return admin(repository.save(e));}
 @Transactional public void delete(UUID id){Event event=get(id);if("PUBLISHED".equals(event.getStatus())){event.setStatus("ARCHIVED");repository.save(event);}else{repository.delete(event);}}
 private Event get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Event not found."));}
 private void apply(Event e,EventRequest r){if(r.endAt()!=null&&!r.endAt().isAfter(r.startAt()))throw new IllegalArgumentException("Event end time must be after its start time.");try{ZoneId.of(r.timezone());}catch(Exception ex){throw new IllegalArgumentException("Invalid event timezone.");}if("virtual".equals(r.category())&&(r.virtualUrl()==null||r.virtualUrl().isBlank()))throw new IllegalArgumentException("Virtual events require a URL.");if("in-person".equals(r.category())&&(r.location()==null||r.location().isBlank()))throw new IllegalArgumentException("In-person events require a location.");if(!r.enableRsvp()&&!r.enableDonate()&&!r.enableVolunteer())throw new IllegalArgumentException("Select at least one event action.");e.setSlug(r.slug());e.setCategory(r.category());e.setStartAt(r.startAt());e.setEndAt(r.endAt());e.setTimezone(r.timezone());e.setLocation(r.location());e.setVirtualUrl(r.virtualUrl());e.setImageUrl(r.imageUrl());e.setDisplayOrder(r.displayOrder()==null?0:r.displayOrder());e.setStatus(r.status());e.setFeatured(r.featured());e.setHighlighted(r.highlighted());e.setCapacity(r.capacity());e.setEnableRsvp(r.enableRsvp());e.setEnableDonate(r.enableDonate());e.setEnableVolunteer(r.enableVolunteer());Map<String,Object> t=new LinkedHashMap<>();t.put("en",map(r.en()));t.put("fr",map(r.en()));e.setTranslations(t);}
 private Map<String,Object> map(EventTranslationRequest t){Map<String,Object> m=new LinkedHashMap<>();m.put("title",t.title());m.put("excerpt",t.excerpt());m.put("description",t.description());m.put("buttonText",t.buttonText());m.put("imageAlt",t.imageAlt());m.put("metaTag",t.metaTag());m.put("agenda",t.agenda()==null?List.of():t.agenda());m.put("roles",t.roles()==null?List.of():t.roles());return m;}
 @SuppressWarnings("unchecked") private Map<String,Object> trans(Event e,String locale){Object v=e.getTranslations().get(locale);if(v instanceof Map<?,?> m)return(Map<String,Object>)m;v=e.getTranslations().get("en");return v instanceof Map<?,?>m?(Map<String,Object>)m:Map.of();}
 private EventResponse admin(Event e){long reserved=registrationRepository.reservedSeats(e.getId());return new EventResponse(e.getId(),e.getSlug(),e.getCategory(),e.getStartAt(),e.getEndAt(),e.getTimezone(),e.getLocation(),e.getVirtualUrl(),e.getImageUrl(),e.getDisplayOrder(),e.getStatus(),e.getFeatured(),e.getHighlighted(),e.getCapacity(),reserved,e.getEnableRsvp(),e.getEnableDonate(),e.getEnableVolunteer(),trans(e,"en"),trans(e,"fr"));}
 private PublicEventResponse localized(Event e,String locale){Map<String,Object>t=trans(e,locale);long reserved=registrationRepository.reservedSeats(e.getId());Integer remaining=e.getCapacity()==null?null:Math.max(0,e.getCapacity()-(int)reserved);return new PublicEventResponse(e.getId(),e.getSlug(),e.getCategory(),e.getStartAt(),e.getEndAt(),e.getTimezone(),e.getLocation(),e.getImageUrl(),e.getDisplayOrder(),e.getFeatured(),e.getHighlighted(),e.getCapacity(),reserved,remaining,remaining!=null&&remaining==0,e.getEnableRsvp(),e.getEnableDonate(),e.getEnableVolunteer(),str(t,"title"),str(t,"excerpt"),str(t,"description"),str(t,"buttonText"),str(t,"imageAlt"),str(t,"metaTag"),list(t,"agenda"),list(t,"roles"));}
 private String str(Map<String,Object>m,String k){Object v=m.get(k);return v==null?"":String.valueOf(v);}@SuppressWarnings("unchecked") private List<String> list(Map<String,Object>m,String k){Object v=m.get(k);return v instanceof List<?>l?l.stream().map(String::valueOf).toList():List.of();}private void validLocale(String l){if(!"en".equals(l)&&!"fr".equals(l))throw new IllegalArgumentException("Unsupported locale.");}
}
